// ReadSessionPromptFromShadow reads the first prompt for a session from the shadow branch.
// Returns an empty string if the prompt cannot be read.
func ReadSessionPromptFromShadow(repo *git.Repository, baseCommit, worktreeID, sessionID string) string {
	// Get shadow branch for this base commit using worktree-specific naming
	shadowBranchName := checkpoint.ShadowBranchNameForCommit(baseCommit, worktreeID)
	ref, err := repo.Reference(plumbing.NewBranchReferenceName(shadowBranchName), true)
	if err != nil {
		return ""
	}

	commit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		return ""
	}

	tree, err := commit.Tree()
	if err != nil {
		return ""
	}

	// Build the path to prompt.txt: .entire/metadata/<session-id>/prompt.txt
	checkpointPath := paths.EntireMetadataDir + "/" + sessionID
	return ReadSessionPromptFromTree(tree, checkpointPath)
}

// PromptResponse represents a single user prompt and assistant response pair.
type PromptResponse struct {
	// Prompt is the user's message
	Prompt string

	// Response is the assistant's response
	Response string

	// Files is the list of files modified during this prompt/response
	Files []string
}

// CheckpointDetails contains detailed information extracted from a checkpoint's transcript.
// This is used by the explain command to display checkpoint content.
type CheckpointDetails struct {
	// Interactions contains all prompt/response pairs in this checkpoint.
	// For strategies like auto-commit/commit, this typically has one entry.
	// For strategies like shadow, this may have multiple entries.
	Interactions []PromptResponse

	// Files is the aggregate list of all files modified in this checkpoint.
	// This is a convenience field that combines files from all interactions.
	Files []string
}

// RepoRootOr returns the git repository root directory, or the current directory
// if not inside a git repository. This is useful for functions that need a fallback.
func RepoRootOr(fallback string) string {
	root, err := RepoRoot()
	if err != nil {
		return fallback
	}
	return root
}
